import sys, json

def sortColors(nums):
    l, mid, r = 0, 0, len(nums)-1
    while mid <= r:
        if nums[mid] == 0:
            nums[l], nums[mid] = nums[mid], nums[l]
            l += 1; mid += 1
        elif nums[mid] == 1:
            mid += 1
        else:
            nums[mid], nums[r] = nums[r], nums[mid]
            r -= 1
    return nums

if __name__ == '__main__':
    data = sys.stdin.read().strip()
    if data:
        nums = json.loads(data)
        sortColors(nums)
        print(json.dumps(nums))

